%[output:37746a38]
%   data: {"dataType":"text","outputData":{"text":"    StudentID         Case         Objective    Solver     Curtailment_MWh    Loss_MWh    GridCost_Yuan    MaxConeGap    SimultaneousPower_MW    MinACVoltage    MaxACVoltage\n    _________    ______________    _________    _______    _______________    ________    _____________    __________    ____________________    ____________    ____________\n\n    2.424e+08    \"case_nongcun\"       \"A\"       \"mosek\"      -3.1602e-07      0.90744         33923        2.9553e-10                 0            0.97133          1.0252   \n    2.424e+08    \"case_nongcun\"       \"B\"       \"mosek\"            10.03      0.66231         40913        4.0984e-10                 0            0.97133               1   \n    2.424e+08    \"case_nongcun\"       \"C\"       \"mosek\"      -4.2989e-08       1.5906         30613        3.2782e-10         1.067e-09               0.95            1.05   \n\n","truncated":false}}
